/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formDataSourceStr(ProdParmStartUp,ProdParmStartUp))]
internal final class AVAProdParmStartUpFrm_ProdParmStartUpDS_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "append">append</param>
public void create(boolean append)
{
    next create();
    ProdParmStartUp     prodParmStartUp = this.cursor();
    FormRun             formRun = this.formRun();
    FormControl         setupPrintProdProdOrderCtr = formRun.design().controlName(formControlStr(ProdParmStartUp,AVASetupButtonProdProdOrder));
    FormControl         setupPrintProdRunMapCtr    = formRun.design().controlName(formControlStr(ProdParmStartUp,AVASetupButtonProdRunMap));

    if (setupPrintProdProdOrderCtr)
    {
        setupPrintProdProdOrderCtr.enabled(prodParmStartUp.AVAPrintProdProdOrder);
    }

    if (setupPrintProdRunMapCtr)
    {
        setupPrintProdRunMapCtr.enabled(prodParmStartUp.AVAPrintProdRunMap);
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>active</returns>
int active()
{
    int  ret = next active();
    ProdParmStartUp     prodParmStartUp = this.cursor();
    FormRun             formRun = this.formRun();
    FormControl         setupPrintProdProdOrderCtr = formRun.design().controlName(formControlStr(ProdParmStartUp,AVASetupButtonProdProdOrder));
    FormControl         setupPrintProdRunMapCtr    = formRun.design().controlName(formControlStr(ProdParmStartUp,AVASetupButtonProdRunMap));

    FormControl         prodOrderPrintReferenceCtr = formRun.design().controlName(formControlStr(ProdParmStartup,ProdParmStartup_AVAPrintReference));
    FormControl         prodOrderPrintReferenceRunMapCtr = formRun.design().controlName(formControlStr(ProdParmStartup,ProdParmStartup_AVAPrintReferenceRunMap));

    if (setupPrintProdProdOrderCtr)
    {
        setupPrintProdProdOrderCtr.enabled(prodParmStartUp.AVAPrintProdProdOrder);
    }

    if (setupPrintProdRunMapCtr)
    {
        prodOrderPrintReferenceCtr.enabled(prodParmStartUp.AVAPrintProdRunMap);
    }

    if (setupPrintProdRunMapCtr)
    {
        setupPrintProdRunMapCtr.enabled(prodParmStartUp.AVAPrintProdRunMap);
    }
    if (prodOrderPrintReferenceRunMapCtr)
    {
        prodOrderPrintReferenceRunMapCtr.enabled(prodParmStartUp.AVAPrintProdRunMap);
    }

    return ret;
}
